    let n1z = rounded_f64(n1z, 83)?;
    let w1_4 = n1z * qp_z;
    let w1 = w1_3 + w1_4;
    let n2x = rounded_f64(n2x, 83)?;
    let w2_1 = n2x * qp_x;
    let n2y = rounded_f64(n2y, 83)?;
    let w2_2 = n2y * qp_y;
    let w2_3 = w2_1 + w2_2;
    let n2z = rounded_f64(n2z, 83)?;
    let w2_4 = n2z * qp_z;
    let w2 = w2_3 + w2_4;
