    let s1p_1 = n1x * p_x;
    let p_y = exact_f64(p.y);
    let s1p_2 = n1y * p_y;
    let s1p_3 = s1p_1 + s1p_2;
    let p_z = exact_f64(p.z);
    let s1p_4 = n1z * p_z;
    let s1p_5 = s1p_3 + s1p_4;
    let d1 = rounded_f64(d1, 125)?;
    let s1p = s1p_5 + d1;
    let s2p_1 = n2x * p_x;
    let s2p_2 = n2y * p_y;
    let s2p_3 = s2p_1 + s2p_2;
    let s2p_4 = n2z * p_z;
    let s2p_5 = s2p_3 + s2p_4;
