    let m_y = largest_magnitude([qp_y, p_y]);
    let m_z = largest_magnitude([qp_z, p_z]);
    let m_n1 = largest_magnitude([n1x, n1y, n1z]);
    let m_d1 = largest_magnitude([d1]);
    let m_n2 = largest_magnitude([n2x, n2y, n2z]);
    let m_d2 = largest_magnitude([d2]);
